    [249409] = "Ферментовано алхіміками.",
    [249410] = "Ферментовано алхіміками.",
    [249430] = "Ферментовано алхіміками.",
    [249431] = "Ферментовано алхіміками.",
    [249432] = "Розроблено інженерами.",
    [249474] = "Навчає, як назавжди зачарувати браслети, щоб отримати +3 до інтелекту.",
    [249475] = "Навчає, як накладати на браслети назавжди чари, щоб збільшити силу зцілення до 8 та шкоду від чарів до 3.",
    [249476] = "Навчає, як створити містичний гриб.",
    [249477] = "Навчає, як створювати Орендарів Срібної Руки.",
    [249478] = "Навчає, як створити ікону з полірованого плавника.",
    [249479] = "Навчає, як назавжди зачарувати зброю, щоб дати шанс отримати Проникливість під час застосування закляття, яке дає +5% Духу на короткий час.",
    [249480] = "Навчає накладати на зброю постійні чари, які можуть активувати Відновлення, коли ворог ухиляється від вашої атаки або парирує її. Відновлення зцілює вас на 5% від максимального запасу здоров’я. Спрацьовує не частіше одного разу на 10 с.",
    [249481] = "Навчає накладати на зброю постійні чари, які можуть активувати Одкровення, коли ваше закляття прямої дії не завдає критичного удару. Одкровення підвищує ймовірність критичного удару наступного закляття на 100%.",
    [249482] = "Навчає, як створити Блискучий посох.",
    [249483] = "Навчає, як створити посох душі.",
    [249484] = "Навчає, як створити Сферу Містичного Прозріння.",
    [249485] = "Навчає, як створити Сферу Душ.",
    [249486] = "Навчає, як назавжди зачарувати браслети, щоб отримати +4 до спритності.",
    [249487] = "Навчає, як створити Покручену Паличку Нижнього Заповіту.",
    [249488] = "Навчає, як назавжди зачарувати браслети, щоб отримати +5 до спритності.",
    [249489] = "Навчає, як накладати на браслети перманентні чари, щоб збільшити силу зцілення до 16 та шкоду від чарів до 6.",
    [249493] = "Навчає, як створювати Кігті Гніву.",
    [249494] = "Навчає, як створити Лібрам Заклику.",
    [249495] = "Навчає, як створити тотем захисту предків.",
    [249496] = "Навчає, як накласти намисто назавжди чари, щоб отримати +5 до Сили.",
    [249502] = "Навчає, як накласти намисто назавжди, щоб збільшити шкоду від чарів та зцілення до 6.",
    [249503] = "Навчає, як накласти намисто назавжди, щоб збільшити силу зцілення до 11 та шкоду від чарів до 4.",
    [249504] = "Навчає, як накласти намисто назавжди чари, щоб отримати +5 до спритності.",
    [249505] = "Навчає, як накласти намисто назавжди чари, щоб отримати +5 до навички захисту.",
    [249506] = "Навчає, як створити Сяючий посох.",
    [249507] = "Навчить вас, як створити посох мрії.",
    [249508] = "Навчає, як створити Провідник зі Справжнього Срібла.",
    [249509] = "Навчає, як створити банку з крученою сутністю.",
    [249510] = "Навчає накладати на нагрудну броню постійні чари, що з імовірністю 25% під час отримання удару поглинають 50 од. шкоди. Спрацьовує не частіше одного разу на 5 с.",
    [249511] = "Навчає, як накласти на дворучну зброю ближнього бою чари, щоб отримати +15 до спритності.",
    [249512] = "Навчає, як створити Паличку Снової Гілки.",
    [249513] = "Навчає, як накласти на дворучну зброю ближнього бою чари, щоб отримати +15 до Сили.",
    [249514] = "Навчає, як назавжди зачарувати браслети, щоб отримати +7 до спритності.",
    [249515] = "Навчає, як створити Меншу Вічну Паличку.",
    [249516] = "Навчає, як накладати на рукавички постійні чари, щоб отримати +10 до навичку зняття шкури.",
    [249522] = "Навчає, як створити Велику Вічну Паличку.",
