    [273129] = "Нестабільна частинка хаосу, саме те, що потрібно для робочого місця анархіста.",
    [273130] = "Запряжені духи нежиті, що використовуються для живлення швейної машинки Вектуса.",
    [273131] = "Приглушені крики хору банші, достатні для живлення таємничого ткацького верстата баронеси.",
    [273141] = "Навчить, як розмістити рибальську стійку на кемпінгу.",
    [273168] = "Це скоріше брошура, ніж справжня книга.",
    [273295] = "Освіжаюча страва з сезонної риби, готова до використання в рецептах.",
    [273298] = "Мммррглумг Печиво гргл мрг мллгргрм. -Лукі, колишній спостерігач за кораблем",
    [273308] = "І руни, і рукопис танцюють по поверхні сторінки, немов павуки. Щось у цій книзі здається зловісним і неприродним.",
    [273309] = "І руни, і рукопис танцюють по поверхні сторінки, немов павуки. Щось у цій книзі здається зловісним і неприродним.",
    [273310] = "І руни, і рукопис танцюють по поверхні сторінки, немов павуки. Щось у цій книзі здається зловісним і неприродним.",
    [273318] = "Містить випадковий асортимент професійних матеріалів для ремісників-підмайстрів.",
    [273319] = "Містить випадковий асортимент професійних матеріалів для учнів-ремісників.",
    [273320] = "Містить випадковий асортимент професійних матеріалів для досвідчених майстрів.",
    [273321] = "Містить випадковий асортимент професійних матеріалів для ремісників.",
    [273642] = "Всередині стрічки вигравірувано ім'я. Хоча його важко прочитати, ініціали «Т» та «Бель» розбірливі.",
    [273658] = "У складках шат Виводкової Матері захована записка.",
    [273659] = "У листі згадується «Пакт» та «Дикий Король»... що це може означати?",
    [273772] = "Документ закритий малиновою восковою печаткою.",
    [273798] = "Всередині стрічки вигравірувано ім'я. Хоча його важко прочитати, ініціали «Т» та «Бель» розбірливі.",
    [273799] = "Перстень загиблого солдата, Томас Белль.",
    [273845] = "Цю ампулу ретельно вирізьбили з одного з кристалів попелу феї поблизу, що надає їй блідо-зеленуватого відтінку. Коли світло потрапляє на неї, здається, що в кристалічних стінках, що ледь помітно мерехтять енергією феї, застряг попіл.",
    [273952] = "Навчає, як виготовляти штани Гайвохоронця.",
    [273953] = "Навчає, як виготовляти Захвати Гайвокера.",
    [273954] = "Навчає, як виготовляти наплічники Гаю.",
    [273955] = "Навчає, як створювати Гайкберегерські Топоти.",
    [273956] = "Навчає, як виготовити кілт Гайвохоронця.",
    [273957] = "Навчає, як виготовити рукавиці Гайохоронця.",
    [273958] = "Навчає, як виготовити Мантію Гаю Хранителя.",
    [273959] = "Навчає, як виготовляти сандалі Гаю.",
    [273960] = "Навчає, як виготовляти набедренники Гаю.",
    [273961] = "Навчає, як виготовляти рукавиці Гайвохоронця.",
    [273962] = "Навчає, як виготовляти наплечники гаю.",
    [273963] = "Навчає, як виготовляти чоботи гаю.",
