    [286076] = "Навчить вас, як зробити маленьку фіолетову ракету.",
    [286077] = "Навчить вас, як зробити маленьку білу ракету.",
    [286078] = "Навчить вас, як зробити маленьку жовту ракету.",
    [286079] = "Навчить вас, як зробити Велику Фіолетову Ракету.",
    [286080] = "Навчить вас, як зробити Велику Білу Ракету.",
    [286081] = "Навчить вас, як зробити Велику жовту ракету.",
    [286082] = "Навчить вас, як зробити фіолетове ракетне скупчення.",
    [286083] = "Навчить вас, як зробити скупчення Білої Ракети.",
    [286084] = "Навчить вас, як зробити жовте ракетне скупчення.",
    [286085] = "Навчить вас, як зробити велике фіолетове ракетне скупчення.",
    [286086] = "Навчить вас, як зробити велике біле ракетне скупчення.",
    [286087] = "Навчить вас, як зробити велике жовте ракетне скупчення.",
    [286153] = "Навчить вас, як готувати пластинчасту броньовицю.",
    [286263] = "Нехай Святе Світло захистить нас у нашій експедиції на замерзлу північ.",
    [286264] = "Я б дуже хотів, щоб ви, маги, витягли голови зі своїх власних... книг.",
    [286265] = "Нехай мої сестри реалізують свій повний потенціал, ім'я Вітрокрилка відоме завдяки їхнім вчинкам.",
    [286266] = "Дай мені сили прийняти те, що я не можу змінити, мужності змінити те, що я можу, і мудрості розпізнати різницю.",
    [286267] = "О, чому ти мене не помічаєш? Аббендіс, я б пішов за тобою куди завгодно. Якби ж тобі мене не помітив...",
    [286268] = "Молюся, щоб, коли настане час, у мене вистачило сил протистояти силам за брамою.",
    [286270] = "Як цей фонтан взагалі працює? Цікаво, чи зміг би я такий зробити.",
    [286271] = "Тураліоне та Аллеріє, де б ви не були, нехай вам буде добре.",
    [286272] = "Нехай мій син Артас завжди діє в найкращих інтересах свого народу.",
    [286273] = "Де Іллідан?",
    [286274] = "<Ти відчуваєш дзвін трьох тонів у своїй голові, третій ледь чутний крізь гамір інших.>",
    [286275] = "Сподіваюся, що мій батько та брати переживуть мене. З мене не буде великого короля.",
    [286279] = "Хотілося б мені подорослішати, таке відчуття, ніби мені вже 10 років.",
    [286280] = "Юний Артас має навчитися терпінню, щоб стримувати свою силу. Я молитимуся, щоб він одного дня навчився керувати обережно, а не силою.",
    [286281] = "У мене вже є королівство в перспективі, земля, якою я керуватиму. Що ж просити? Можливо, заморожену булочку...",
    [286283] = "Я мрію колись потрапити на пенсію у свій власний охайний маленький маєток, де мені будуть товариство собаки.",
    [286284] = "Бранн Бронзобородий був тут.",
    [286287] = "Іноді... мені хочеться, щоб хтось підійшов і просто міцно, довго мене обійняв.",
    [286288] = "Артасе, коханий мій, будь ласка, повернися до мене.",
    [286290] = "Послухай, маленький фонтанчик бажань. Ти віддаси мені всю свою силу, якщо знатимеш, що для тебе добре.",
    [286291] = "Сподіваюся, що ми з сестрами виростемо та одружимося разом. Ця монета виглядає дуже старою.",
    [286292] = "Я бажаю, щоб мій дорогий Таелан виріс достатньо сильним, щоб захищати людей, про яких він піклується.",
    [286293] = "Хотіла б я знати, як ти пережила мій гнів, маленьке фонтанчику.",
    [286294] = "Розтлумачте мій сон про маленький фонтан. Чому я завжди маю дивитися на своїх родичів згори та рухати їх, як пішаків?",
    [286298] = "Здається, мої дні підробітку поштовим працівником добігають кінця.",
    [286299] = "Громе, спочивай спокійно, старий друже.",
    [286300] = "Це не має сенсу. Навіщо я кидаю монету у фонтан?",
    [286302] = "Скільки монет сяє у басейні... Можливо, ніхто не помітить, якщо я візьму лише одну.",
    [286304] = "Шкода, що мій двоюрідний брат не займався нічим, крім як недбало тягав дрова...",
    [286306] = "Шкода, що капітан Сандерс не поспішав з моєю партією вина.",
    [286307] = "Я бажаю щастя та прийняття для своєї доньки. Вона почувається тут такою недоречною...",
    [286308] = "Чи можна мені зручніше сідло? У мене болять задні кінцівки.",
    [286309] = "Сподіваюся, троль помре, прямо ЗАРАЗ...",
    [286310] = "Бути шахраєм – важка праця. Сподіваюся, що колись зможу займатися єдиною справжньою пристрастю свого життя...",
    [286311] = "Сподіваюся, що врешті-решт я опинюся в іншій книзі.",
    [286312] = "Шкода, що мій батько не повернувся...",
    [286313] = "Шкода, що я не зберіг ту монету...",
    [286314] = "Шкода, що люди перестануть скидати мої іграшки з полиці.",
    [286315] = "Я міг би використати цю мідь для чогось продуктивного. Можливо, для чогось зі мотузкою та машиною.",
    [286316] = "Тут навіть немає магії.",
    [286317] = "Як у таверні може закінчитися ель!",
    [286318] = "Мені не вистачає мого меча та щита. Я почуваюся таким голим без меча та щита.",
    [286327] = "Ну ж бо, Ноздорму. Що ж мені було робити після цього?",
    [286328] = "Як мені довести, що вони нас скопіювали цим фонтаном?",
}
for id, flavor in pairs(item_flavor) do
    local entry = addonTable.item[id]
    if entry and entry.flavor == nil then entry.flavor = flavor end
end

